@inject TopLayerPinService Pins
<div @ref="_bar" class="tm-pin-on-top my-bar" hidden="@(!_show)">…</div>
@code {
    ElementReference _bar; TopLayerPin? _pin;
    protected override async Task OnAfterRenderAsync(bool first)
    {
        if (first) _pin = await Pins.PinAsync(_bar, new TopLayerPinOptions { Priority = 100 });
    }
    public async ValueTask DisposeAsync() { if (_pin is not null) await _pin.DisposeAsync(); }
}
